from fractions import Fraction
from math import comb


def solve_math_problem(n: int, k: int, m: int, target: int) -> Fraction:
    """
    Find real number A such that the coefficient of x^n in the polynomial
    (1 + x^k)^n + A * (x * (1 - x^2)^2)^m equals target.

    Args:
        n: exponent of the first term and power of the binomial
        k: power of x in the first term's binomial
        m: exponent applied to the second term
        target: desired coefficient of x^n

    Returns:
        Fraction representing the value of A

    Raises:
        ValueError: if the coefficient of A is zero (no unique solution)
    """
    # Coefficient of x^n in (1 + x^k)^n
    if n % k == 0:
        j = n // k
        if 0 <= j <= n:
            coeff_first = comb(n, j)
        else:
            coeff_first = 0
    else:
        coeff_first = 0

    # Coefficient of x^n in (x(1-x^2)^2)^m = x^m * (1-x^2)^{2m}
    # Need x^{n-m} from (1-x^2)^{2m} = sum_{j} C(2m,j)*(-1)^j * x^{2j}
    # So 2j = n-m, j = (n-m)/2
    diff = n - m
    if diff >= 0 and diff % 2 == 0:
        j = diff // 2
        if 0 <= j <= 2 * m:
            coeff_second = (-1) ** j * comb(2 * m, j)
        else:
            coeff_second = 0
    else:
        coeff_second = 0

    if coeff_second == 0:
        raise ValueError(
            "Coefficient of A is zero; no unique solution exists."
        )

    A = Fraction(target - coeff_first, coeff_second)
    return A
